// Columnar vector reader: each ring is a Float64Array of x, y pairs.
export function ringsOf(coords, ends) {
  const rings = [];
  let start = 0;
  for (const end of ends) {
    rings.push(new Float64Array(coords.subarray(start * 2, end * 2)));
    start = end;
  }
  return rings;
}

