// Shapefile writer: the bounding box of each polygon record.
export function recordBox(geometry) {
  const flat = geometry.rings.flatMap((ring) => ring);
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (let i = 0; i < flat.length; i += 2) {
    minX = Math.min(minX, flat[i]);
    maxX = Math.max(maxX, flat[i]);
    minY = Math.min(minY, flat[i + 1]);
    maxY = Math.max(maxY, flat[i + 1]);
  }
  return [minX, minY, maxX, maxY];
}
